// Stage 3 & 4: Deterministic Rule Verification and Match Reasons Formatting
const items = $input.all();
const importId = $('Matching Webhook Trigger').item.json.body.import_id;
const matches = [];

for (const item of items) {
  const row = item.json;

  const reasons = [
    {
      criterion: 'monthly_income',
      passed: true,
      message: `Monthly income ₹${Number(row.monthly_income).toLocaleString('en-IN')} meets published threshold of ₹${Number(row.min_monthly_income).toLocaleString('en-IN')}`
    },
    {
      criterion: 'credit_score',
      passed: true,
      message: `Credit score ${row.credit_score} satisfies minimum threshold of ${row.min_credit_score}`
    },
    {
      criterion: 'age',
      passed: true,
      message: `Age ${row.age} is within eligible range [${row.min_age}, ${row.max_age}]`
    },
    {
      criterion: 'employment_status',
      passed: true,
      message: `Employment status '${row.employment_status}' is explicitly accepted`
    }
  ];

  matches.push({
    json: {
      user_id: row.user_id,
      product_id: row.product_id,
      import_id: importId,
      rule_version: 'v1.0-n8n-sql-funnel',
      match_score: 100.00,
      match_reasons: JSON.stringify(reasons),
      status: 'CONFIRMED'
    }
  });
}

return matches;

