INSERT INTO matches (
  user_id, product_id, import_id, rule_version, match_score, match_reasons, status, created_at
) VALUES (
  $1::uuid, $2::uuid, $3::uuid, $4, $5, $6::jsonb, $7, NOW()
)
ON CONFLICT (user_id, product_id, import_id) DO NOTHING;
